<template><details class="account-menu"><summary class="account-trigger" :class="{ 'is-collapsed': collapsed }"><img v-if="avatarSrc" class="avatar avatar-image" :src="avatarSrc" alt="" @error="avatarFailed = true" /><span v-else class="avatar">{{ initial }}</span><span v-if="!collapsed" class="account-id">{{ label }}</span></summary><div class="account-list"><button v-for="account in authStore.accounts" :key="account.user_id" class="account-option" :disabled="authStore.isSwitching || account.user_id === authStore.activeAccountId" @click="switchAccount(account.user_id)"><img v-if="account.avatar_url" class="avatar avatar-image" :src="account.avatar_url" alt="" /><span v-else class="avatar">{{ accountInitial(account) }}</span><span>{{ displayName(account) }}</span><span v-if="account.user_id === authStore.activeAccountId">✓</span></button><md-text-button @click="emit('add-account')">{{ t('auth.addAccount') }}</md-text-button><md-text-button :disabled="!authStore.isLoggedIn" @click="authStore.logout()">{{ t('auth.logout') }}</md-text-button></div></details></template>
<script setup lang="ts">
import { computed, ref, watch } from "vue"; import { useI18n } from "vue-i18n"; import { useAuthStore } from "../../stores/auth"; import { errorMessage, type AccountEntry } from "../../api/tauri"; import { notify } from "../../ui/notify";
defineProps<{ collapsed: boolean }>(); const emit = defineEmits<{ (e: "add-account"): void }>(); const { t } = useI18n(); const authStore = useAuthStore(); const avatarFailed = ref(false); const avatarSrc = computed(() => avatarFailed.value ? "" : authStore.avatarUrl); const label = computed(() => authStore.isLoggedIn ? authStore.pixivId || authStore.name : t("auth.accounts")); const initial = computed(() => label.value.charAt(0).toUpperCase()); watch(() => authStore.avatarUrl, () => { avatarFailed.value = false; }); function displayName(account: AccountEntry) { return account.pixiv_id || account.name || account.user_id; } function accountInitial(account: AccountEntry) { return displayName(account).charAt(0).toUpperCase(); } async function switchAccount(id: string) { try { await authStore.switchAccount(id); notify(t("auth.switchSuccess", { name: displayName(authStore.accounts.find(account => account.user_id === id)!) })); } catch (error) { notify(errorMessage(error) || t("auth.switchFailed")); } }
</script><style scoped>.account-menu{position:relative}.account-trigger{display:flex;align-items:center;gap:8px;list-style:none;cursor:pointer}.account-trigger::-webkit-details-marker{display:none}.avatar{display:grid;place-items:center;flex:none;width:32px;height:32px;border-radius:50%;color:var(--md-sys-color-on-primary-container);font-weight:600;background:var(--md-sys-color-primary-container)}.avatar-image{object-fit:cover}.account-id{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.account-list{position:absolute;z-index:20;bottom:calc(100% + 8px);left:0;display:grid;min-width:220px;padding:8px;border-radius:12px;background:var(--md-sys-color-surface-container);box-shadow:0 4px 12px rgb(0 0 0 / 18%)}.account-option{display:flex;align-items:center;gap:8px;padding:8px;background:none;border:0;color:var(--ink);font:inherit;text-align:left;cursor:pointer}.account-option:disabled{opacity:.65}.is-collapsed{justify-content:center}</style>
